251	\begin{theorem}\label{thm:ms-from-ac}
252		\lean{MIPStarRE.QPBT.obsOf, MIPStarRE.QPBT.exists_ms_perfect_strategy_of_anticommuting}
253		\leanok
254		\uses{def:ms-game, def:consistent-measurement, def:spcc, def:EPR, def:tensor-product-value}
255		Let $A = \{A_b\}_{b \in \F_2}$ and $B = \{B_b\}_{b \in \F_2}$ be two-outcome projective measurements acting on $(\C^q)^{\ot n}$ that are consistent on $\ket{\mathrm{EPR}_q}^{\ot n}$ (Definition~\ref{def:consistent-measurement}), and let $\mathcal O_A = A_0 - A_1$ and $\mathcal O_B = B_0 - B_1$ be the corresponding $\pm 1$-valued observables. Suppose that $\mathcal O_A \mathcal O_B = - \mathcal O_B \mathcal O_A$. Then there exists a symmetric strategy $\mathcal S = (\psi, M)$ for the Magic Square game with the following properties:
256		\begin{enumerate}
257			\item $\mathcal S$ is an SPCC (symmetric, projective, consistent, commuting) strategy of value $1$;
258			\item the state is $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot n} \ot \ket{\mathrm{EPR}_2}$;
259			\item for $b \in \{0,1\}$, $M^{\mathsf{Variable}_1}_b = A_b \ot I$ and $M^{\mathsf{Variable}_5}_b = B_b \ot I$.
260		\end{enumerate}
261	\end{theorem}
262	\begin{proof}
263		\uses{def:consistent-measurement}
264		The strategy is based on the canonical two-qubit operator solution of the Magic Square, with the state $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot n} \ot \ket{\mathrm{EPR}_2}$ and the cells of the grid assigned the $\pm 1$-valued observables
265		\[
266			\begin{array}{ccc}
267				\mathcal O_A \ot I & I \ot \sigma^X & \mathcal O_A \ot \sigma^X \\[2pt]
268				I \ot \sigma^Z & \mathcal O_B \ot I & \mathcal O_B \ot \sigma^Z \\[2pt]
269				\mathcal O_A \ot \sigma^Z & \mathcal O_B \ot \sigma^X & \mathcal O_A \mathcal O_B \ot \sigma^Z \sigma^X
270			\end{array}
271		\]
272		on $(\C^q)^{\ot n} \ot \C^2$: on question $\mathsf{Variable}_j$ a player measures the two-outcome projective measurement of the observable in cell $j$, and on question $\mathsf{Constraint}_i$ a player simultaneously performs the three measurements of the corresponding row or column; item~3 holds by construction. Anticommutation of $\mathcal O_A$ and $\mathcal O_B$ gives
273		\begin{equation}\label{eq:am-i-hermitian}
274			\mathcal O_A \mathcal O_B \ot \sigma^Z \sigma^X
275			= - \mathcal O_A \mathcal O_B \ot \sigma^X \sigma^Z
276			= \mathcal O_B \mathcal O_A \ot \sigma^X \sigma^Z
277			= (\mathcal O_A \mathcal O_B \ot \sigma^Z \sigma^X)^\dagger\;,
278		\end{equation}
279		so the bottom-right cell is Hermitian, and it squares to the identity; hence every cell is a genuine $\pm 1$-valued observable. The three observables in each row and each column commute pairwise --- for the third row and third column this again uses Equation~\eqref{eq:am-i-hermitian} --- so the $\mathsf{Constraint}$ measurements are well defined, and the strategy is symmetric, projective, and commuting. A two-outcome projective measurement is consistent on a state if and only if its observable $\mathcal O$ satisfies $\mathcal O \ot I \ket{\psi} = I \ot \mathcal O \ket{\psi}$; since $A$ and $B$ are consistent on $\ket{\mathrm{EPR}_q}^{\ot n}$ by hypothesis and $\sigma^X$, $\sigma^Z$ are consistent on $\ket{\mathrm{EPR}_2}$, each cell observable is a product of consistent, commuting factors and is therefore consistent on $\ket{\psi}$, and consistency of the $\mathsf{Constraint}$ measurements follows from the cellwise consistencies together with commutativity. Finally, the observables in each row and each of the first two columns multiply to $I$, while those of the third column multiply to $-I$; for the measurement $\{S_0, S_1\}$ obtained by measuring a $\mathsf{Constraint}_i$ triple and outputting the sum of the three bits, the observable $S_0 - S_1$ equals the product of the three cell observables, hence $\pm I$, which forces the three answer bits to sum to $0$ (respectively, $1$ for $\mathsf{Constraint}_6$) with certainty. Together with consistency this shows that every check of the Magic Square game is passed with probability $1$, so the strategy has value $1$.
280	\end{proof}
