282	\section{The Pauli basis test}
283	% Paper label sec:qld-game kept for cross-reference fidelity.
284	\label{sec:qld-game}
285	
286	The Pauli basis test is the quantum low individual degree test of Natarajan and Vidick, in the slightly modified form introduced by Natarajan and Wright~\cite{Natarajan2018NEEXP}. Informally, the test certifies that the players share the state $\ket{\mathrm{EPR}_q}^{\ot M}$, where $M = 2^m$. On a question of type $(\mathsf{Pauli}, W)$ with $W \in \{X,Z\}$, a player is expected to measure the generalized Pauli basis POVM $\{\tau^W_h\}_{h \in \F_q^M}$ of Chapter~\ref{chap:qpbt-algebra} and report the outcome $h$. Most subtests probe limited information about $h$: given a point $u_W \in \F_q^m$, a player is expected to report the evaluation $g_h(u_W)$ of the low-degree encoding $g_h$ of $h$, and for a fixed basis $W$ these probes are checked against each other by the classical low individual degree game of Section~\ref{sec:ld-verifier}. Consistency \emph{between} the two bases is checked through two-outcome probes: given additionally $r_W \in \F_q$, a player reports $\tr(g_h(u_W)\, r_W) \in \F_2$. The two binary measurements obtained in this way for $W = X$ and $W = Z$ either commute or anticommute, according to the value $\gamma \in \F_2$ of Equation~\eqref{eq:gamma-value} below. When $\gamma = 0$ the verifier checks commutation directly by asking for both bits simultaneously; when $\gamma = 1$ the verifier checks anticommutation by playing the Magic Square game, using Theorem~\ref{thm:ms-from-ac}.
287	
288	\begin{definition}[Admissible parameters]\label{def:admissible}
289		\uses{def:admissible-size}
290		% The source introduces q, m, d in \N with \N the positive integers
291		% (references/qpbt-paper/04_preliminaries.tex:6 and
292		% references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:903-905),
293		% so d >= 1 is implicit in its notion of admissibility (lines 958-961 there);
294		% we state it explicitly. It is load-bearing: at d = 0 the soundness function
295		% delta_qld of thm:pauli vanishes identically while every strategy satisfies
296		% the success hypothesis at eps = 1, and the low-degree check of
297		% def:pauli-win-predicate invokes the classical game at ldparams = (q,m,d,1),
298		% whose domain (Definition def:ld-game) requires d >= 1. The hypothesis
299		% propagates to lem:pauli-completeness, thm:pauli, and cor:pauli-binary
300		% through their quantification over admissible tuples.
301		The tuple $\mathsf{qldparams} = (q,m,d)$ is \emph{admissible} if $d \ge 1$, $q$ is an admissible field size (Definition~\ref{def:admissible-size}), and $m$ divides $q$. Since an admissible field size satisfies $q \ge 2$, the divisibility forces $m \ge 1$, so an admissible tuple has all entries positive.
302	\end{definition}
303	
304	\begin{definition}[Question distribution of the Pauli basis test]\label{def:pauli-question-distribution}
305		\uses{def:admissible, def:ld-question-distribution, def:ms-game, def:cl-func, def:cl-dist, def:graph-distribution}
306		% Admissibility of the full tuple is required here, not only the divisibility m | q:
307		% the source parametrizes the Pauli basis test by the tuple qldparams introduced
308		% together with Definition def:admissible (references/qpbt-paper/
309		% 08_classical_and_quantum_low_degree_tests.tex:958-1075), and both the fixed binary
310		% identification of F_q used by the map chi and the trace tr in eq:gamma-value
311		% require q to be a power of 2.
312		The game $\mathfrak{G}^{\mathrm{Pauli}}$ (also $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$) is parametrized by an admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}): admissibility makes $q$ a power of $2$, so that the field $\F_q$, its fixed identification with binary strings (Chapter~\ref{chap:qpbt-algebra}), and the trace $\tr\colon \F_q \to \F_2$ used by the win predicate below are defined, and it provides the divisibility $m \mid q$ required by the index map $\chi$ of Definition~\ref{def:ld-question-distribution}. The question type set is
313		\begin{equation}
314			\label{eq:pauli-type}
315			\mathcal T^{\mathrm{pauli}} = \bigl( \{\mathsf{Point}, \mathsf{ALine}, \mathsf{DLine}, \mathsf{Pauli}, \mathsf{Pair}\} \times \{X,Z\} \bigr) \cup \mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}\}\;,
316		\end{equation}
317		where $\mathcal T^{\mathrm{ms}}$ is the type set of the Magic Square game (Definition~\ref{def:ms-game}).
318	
319		The ambient space is $V^{\mathrm{pauli}} = (\F_q^m)^2 \times \F_q \times \F_q^m \times (\F_q)^2$, decomposed into the register subspaces $V_X, V_Z$ (each $m$-dimensional over $\F_q$), $V_I$ ($1$-dimensional), $V_V$ ($m$-dimensional), and $V_{R_X}, V_{R_Z}$ ($1$-dimensional each); elements of $V^{\mathrm{pauli}}$ are written $(u_X, u_Z, s, v, r_X, r_Z)$. For each type $t \in \mathcal T^{\mathrm{pauli}}$ define a CL function $L_t\colon V^{\mathrm{pauli}} \to V^{\mathrm{pauli}}$ as follows, where $L_{\mathsf{Point}}, L_{\mathsf{ALine}}, L_{\mathsf{DLine}}$ are the CL functions of Definition~\ref{def:ld-question-distribution}:
320		\begin{enumerate}
321			\item for $W \in \{X,Z\}$, $L_{(\mathsf{Point},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{Point}}(u_W,s,v)$, a $1$-level CL function, where the range $V_W \oplus V_I \oplus V_V$ of $L_{\mathsf{Point}}$ is embedded in $V^{\mathrm{pauli}}$ in the natural way (the same convention applies in items~2 and~3);
322			\item for $W \in \{X,Z\}$, $L_{(\mathsf{ALine},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{ALine}}(u_W,s,v)$, a $2$-level CL function;
323			\item for $W \in \{X,Z\}$, $L_{(\mathsf{DLine},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{DLine}}(u_W,s,v)$, a $3$-level CL function;
324			\item for $t \in \mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$, $L_t(u_X,u_Z,s,v,r_X,r_Z) = (u_X,u_Z,0,0,r_X,r_Z)$, the $1$-level CL function projecting onto $V_X \oplus V_Z \oplus V_{R_X} \oplus V_{R_Z}$;
325			\item for $W \in \{X,Z\}$, $L_{(\mathsf{Pauli},W)} = 0$, the identically zero ($0$-level) CL function.
326		\end{enumerate}
327		The maps $L_{(\mathsf{Point},W)}$, $L_{(\mathsf{ALine},W)}$, $L_{(\mathsf{DLine},W)}$ act as the zero function on $V_{\overline W} \oplus V_{R_X} \oplus V_{R_Z}$, where $\overline W$ denotes the basis other than $W$.
328	
329		The \emph{type graph} $G^{\mathrm{pauli}}$ has vertex set $\mathcal T^{\mathrm{pauli}}$ and the following edges: all $18$ edges of the Magic Square type graph $G^{\mathrm{ms}}$ (Definition~\ref{def:ms-game}); the edges
330		\begin{align*}
331			&(\mathsf{ALine},X) \,\text{---}\, (\mathsf{Point},X)\;, &&(\mathsf{DLine},X) \,\text{---}\, (\mathsf{Point},X)\;, &&(\mathsf{Point},X) \,\text{---}\, (\mathsf{Pauli},X)\;,\\
332			&(\mathsf{ALine},Z) \,\text{---}\, (\mathsf{Point},Z)\;, &&(\mathsf{DLine},Z) \,\text{---}\, (\mathsf{Point},Z)\;, &&(\mathsf{Point},Z) \,\text{---}\, (\mathsf{Pauli},Z)\;,\\
333			&(\mathsf{Point},X) \,\text{---}\, \mathsf{Variable}_1\;, &&(\mathsf{Point},Z) \,\text{---}\, \mathsf{Variable}_5\;, &&\\
334			&(\mathsf{Point},X) \,\text{---}\, (\mathsf{Pair},X)\;, &&(\mathsf{Pair},X) \,\text{---}\, \mathsf{Pair}\;, &&\\
335			&(\mathsf{Point},Z) \,\text{---}\, (\mathsf{Pair},Z)\;, &&(\mathsf{Pair},Z) \,\text{---}\, \mathsf{Pair}\;; &&
336		\end{align*}
337		and, in addition, a self-loop at every vertex.
338	
339		% The type pair is drawn from the graph distribution of Definition
340		% def:graph-distribution, matching the source's formal definition
341		% (references/qpbt-paper/07_types.tex:84-93 together with
342		% references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:1115-1120).
343		% Sampling an undirected edge uniformly and then ordering its
344		% endpoints uniformly would be a different distribution here: it gives each self-loop
345		% twice the relative mass of an oriented non-loop pair, and G^pauli has a self-loop
346		% at every vertex.
347		The question distribution of $\mathfrak{G}^{\mathrm{Pauli}}$ is the typed CL distribution on $\mathcal T^{\mathrm{pauli}} \times V^{\mathrm{pauli}} \times \mathcal T^{\mathrm{pauli}} \times V^{\mathrm{pauli}}$ obtained by sampling the type pair $(t_{\mathrm A}, t_{\mathrm B})$ from the graph distribution $\mu_{G^{\mathrm{pauli}}}$ of Definition~\ref{def:graph-distribution}, that is, uniformly at random among all ordered pairs of types whose underlying unordered pair $\{t_{\mathrm A}, t_{\mathrm B}\}$ is an edge of $G^{\mathrm{pauli}}$, self-loops included; sampling $z \in V^{\mathrm{pauli}}$ uniformly at random; and setting $x_w = L_{t_w}(z)$ for $w \in \{\mathrm A,\mathrm B\}$. Explicitly, if $z = (u_X,u_Z,s,v,r_X,r_Z)$, then a player whose type is $(\mathsf{Point},W)$ receives $u_W$; a player whose type is $(\mathsf{ALine},W)$ receives $(u_0, s)$ with $u_0 = L^{\mathrm{Ln}}_{e_i}(u_W)$ and $i = \chi(s)$; a player whose type is $(\mathsf{DLine},W)$ receives $(u_0, s, v')$ with $i = \chi(s)$, $v' = \pi_{i-1}(v)$, and $u_0 = L^{\mathrm{Ln}}_{v'}(u_W)$; a player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ receives $(u_X, u_Z, r_X, r_Z)$; and a player whose type is $(\mathsf{Pauli},W)$ receives $0$.
348	\end{definition}
