599	\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
600		\lean{MIPStarRE.QPBT.primeTauObservable_mul}
601		\lean{MIPStarRE.QPBT.primeTauObservable_pow}
602		\lean{MIPStarRE.QPBT.primeTauObservable_pow_char}
603		\lean{MIPStarRE.QPBT.primeTauObservable_isUnitary}
