649	\begin{lemma}[Fourier cancellation over a subspace]\label{lem:cancellation}
650		\lean{MIPStarRE.QPBT.ffChar_dotProduct_submodule_expect_eq_zero}
651		\leanok
652		\uses{def:dot-product-orthogonal, def:subfield-trace}
653		Let $V$ be a subspace of $\F_q^k$ and let $\omega = e^{2\pi i/p}$, where
654		$p$ is the characteristic of $\F_q$ and $\tr = \tr_{q \to p}$. For all
655		$v \notin V^\perp$,
656		\[
657			\E_{\bu \sim V}\, \omega^{\tr(\bu \cdot v)} = 0\;,
658		\]
659		where the expectation is over a uniformly random vector $\bu$ in $V$.
660	\end{lemma}
661	\begin{proof}
662		This is Fact 3.2 of \cite{Natarajan2018NEEXP}. Since $v \notin V^\perp$,
663		the $\F_q$-linear functional $u \mapsto u \cdot v$ is not identically zero
664		on $V$, hence surjective onto $\F_q$; composing with the nonzero map $\tr$
665		shows that there is $u_0 \in V$ with $\tr(u_0 \cdot v) \neq 0$. Writing $C$
666		for the expectation, translation invariance of the uniform distribution on
667		$V$ gives
668		$C = \E_{\bu \sim V}\, \omega^{\tr((\bu + u_0) \cdot v)}
669		= \omega^{\tr(u_0 \cdot v)}\, C$, and $\omega^{\tr(u_0 \cdot v)} \neq 1$
670		forces $C = 0$.
671	\end{proof}
