688	\begin{proof}
689		\uses{def:generalized-pauli, lem:cancellation}
690		Each $\ket{b_W}$ is an eigenvector of $\tau^W(a)$ with eigenvalue
691		$\omega^{\tr(a \cdot b)}$: for $W = Z$ this is immediate from the
692		definition, and for $W = X$ it follows from the single-qudit computation
693		$\tau^X(a)\ket{e_X} = \omega^{\tr(ae)}\ket{e_X}$, applied factor by factor.
694		Expanding $\tau^W(a)$ in the orthonormal eigenbasis
695		$\{\ket{b_W}\}_{b \in \F_q^n}$ gives the first display. For the inversion,
696		substitute the first display and exchange the order of summation; by
697		Lemma~\ref{lem:cancellation} applied with $V = \F_q^n$ (so that
698		$V^\perp = \{0\}$), the inner expectation vanishes unless $b' = b$, where
699		it equals $1$.
700	\end{proof}
701	
702	Since only admissible field sizes $q = 2^k$ arise in the Pauli basis test, the
703	maximally entangled state $\ket{\mathrm{EPR}_q}$ and the qudit Pauli
704	projectors are isomorphic to tensor products of qubit EPR states
705	$\ket{\mathrm{EPR}_2}$ and qubit Pauli projectors. This is the content of the
706	next lemma, which is what allows the Pauli basis test to self-test Pauli
707	observables and maximally entangled states over \emph{qubits}
708	(Chapter~\ref{chap:qpbt-test}).
709	
710	\begin{lemma}[Qudit-to-qubit isomorphism]\label{lem:pauli-binary}
711		\lean{MIPStarRE.QPBT.qubitPauliProj, MIPStarRE.QPBT.exists_qubitIsometry}
712		\leanok
713		\uses{def:admissible-size, def:subfields-kappa, def:binary-representation,
714			def:generalized-pauli, def:EPR}
715		For all admissible field sizes $q = 2^k$ and integers $L \ge 0$, there
716		exists an isomorphism $\phi : (\C^q)^{\ot L} \to (\C^2)^{\ot Lk}$ such that
717		\begin{equation}\label{eq:epr-q-to-epr-2}
718			\phi \ot \phi\, \ket{\mathrm{EPR}_q}^{\ot L}
719			= \ket{\mathrm{EPR}_2}^{\ot Lk}
720		\end{equation}
721		(applying the natural identifications between
722		$(\C^q)^{\ot L} \ot (\C^q)^{\ot L}$ and $(\C^q \ot \C^q)^{\ot L}$, and
723		between $(\C^2)^{\ot Lk} \ot (\C^2)^{\ot Lk}$ and
724		$(\C^2 \ot \C^2)^{\ot Lk}$). Moreover, for all $W \in \{X, Z\}$ and all
725		$u \in \F_q^L$,
726		\begin{equation}\label{eq:pauli-q-to-pauli-2}
727			\tau^W_u = \phi^\dagger\,
728			\Bigl(\bigotimes_{i=1}^L \bigotimes_{j=1}^k
729			\sigma^W_{u_{ij}}\Bigr)\, \phi\;.
730		\end{equation}
731		Here $(u_{ij})_{i,j}$ is the array of $\F_2$ values with
732		$u_i = \sum_j u_{ij} e_j$ for all $i \in \{1, \dots, L\}$, where
733		$\{e_1, \dots, e_k\}$ is the fixed self-dual normal basis of $\F_q$ over
734		$\F_2$ of Definition~\ref{def:binary-representation}; and for
735		$i \in \{1, \dots, L\}$ and $j \in \{1, \dots, k\}$ the $(i,j)$-th factor
736		$\sigma^W_{u_{ij}}$ denotes the projector
737		$\frac{1}{2}\bigl(\Id + (-1)^{u_{ij}} \sigma^W(1)\bigr)$ acting on the
738		$s$-th qubit, where $s = (i-1)k + j$.
739		The formal product indices are zero-based: values $(i-1,j-1)$ correspond to
740		the paper's pair $(i,j)$.
741	\end{lemma}
742	\begin{proof}
743		\uses{lem:pauli-observable-expansion, lem:downsize_field,
744			lem:twisted-commutation}
745		Define the isometry $\theta : \C^q \to (\C^2)^{\ot k}$ by
746		$\theta\ket{a} = \ket{a_1} \ot \dots \ot \ket{a_k}$, where
747		$\kappa(a) = (a_1, \dots, a_k)$ is the binary representation with respect
748		to the fixed basis; since $\kappa$ is a bijection, $\theta$ is a unitary
749		and $\theta \ot \theta\, \ket{\mathrm{EPR}_{2^k}} =
750		\ket{\mathrm{EPR}_2}^{\ot k}$. For $a \in \F_q$ with
751		$\kappa(a) = (a_1, \dots, a_k)$, the inversion formula of
752		Lemma~\ref{lem:pauli-observable-expansion} gives
753		$\tau^W_a = \E_{b \in \F_q} (-1)^{\tr(ab)}\, \tau^W(b)$; writing
754		$b = \sum_j b_j e_j$, self-duality of the basis gives
755		$b_j = \tr(b e_j)$ (item 1 of Lemma~\ref{lem:downsize_field}) and hence
756		$\tr(ab) = \sum_j a_j b_j$. The product relation of
757		Lemma~\ref{lem:twisted-commutation} factors
758		$\tau^W(b) = \prod_j \tau^W(b_j e_j)$, so the expectation factors over
759		independent $b_1, \dots, b_k \in \F_2$. A computation on basis states shows
760		that for all $c \in \F_2$, $\tau^W(c e_j) = \theta^\dagger\,
761		\sigma^{W,j}(c)\, \theta$, where $\sigma^{W,j}(c)$ is the identity for
762		$c = 0$ and the Pauli $W$ observable acting on the $j$-th qubit of
763		$(\C^2)^{\ot k}$ for $c = 1$. Averaging,
764		$\E_{b_j \in \F_2} (-1)^{a_j b_j} \sigma^W(b_j) =
765		\frac{1}{2}\bigl(\Id + (-1)^{a_j}\sigma^W(1)\bigr) = \sigma^W_{a_j}$,
766		whence $\tau^W_a = \theta^\dagger \bigl(\bigotimes_j
767		\sigma^W_{a_j}\bigr) \theta$. Taking $\phi = \theta^{\ot L}$ and tensoring
768		the last identity over the $L$ qudits, using
769		$\tau^W_u = \bigotimes_{i=1}^L \tau^W_{u_i}$, yields both displayed
770		identities.
771	\end{proof}
772	
773	\begin{remark}\label{rem:pauli-binary-source}
774		In the source statement of Lemma~\ref{lem:pauli-binary} in
775		\cite{Ji2020MIPStar}, the index range of the qubit factor is printed as
776		$j \in \{1, \dots, q\}$; the intended range, used above, is
777		$j \in \{1, \dots, k\}$, as the $i$-th qudit is mapped to $k$ qubits. The
778		source also quantifies over arbitrary integers $L$; the statement above
779		takes $L$ to be a natural number, including zero, and uses the usual
780		empty-product convention for the tensor powers when $L=0$.
781	\end{remark}

